window.docContents[217].resolve({"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Quiver/#Chapter2___Definition2___8___1___heading-1":{"contents":"Definition 2.8.1. A quiver Q is a directed graph, possibly with self-loops and/or multiple edges between two vertices.\n\n","context":"Introduction to Representation Theory\t2. Basic notions of representation theory\t2.8. Quivers\tQuiver","header":"2.8. Quivers","id":"/2___-Basic-notions-of-representation-theory/2___8___-Quivers/Quiver/#Chapter2___Definition2___8___1___heading-1"},"/6___-Quiver-representations/6___4___-Roots/Remark-6___4___4___-Finiteness-of-roots/#Chapter6___Remark6___4___4":{"contents":"Remark 6.4.4. There can be only finitely many roots, since all of them have to lie in some ball.\n\n\n\n","context":"Introduction to Representation Theory\t6. Quiver representations\t6.4. Roots\tRemark 6.4.4: Finiteness of roots","header":"Remark 6.4.4: Finiteness of roots","id":"/6___-Quiver-representations/6___4___-Roots/Remark-6___4___4___-Finiteness-of-roots/#Chapter6___Remark6___4___4"}});
